def safe_divide_list(numerator: list[int], denominator: list[int]) -> list[float]:
    min_length = min(len(numerator), len(denominator))
    result = []
    for i in range(min_length):
        if denominator[i] == 0:
            result.append(float('nan'))
        else:
            result.append(numerator[i] / denominator[i])
    return result

